function renderTime(){state.now=new Date();const w=windowNow(),start=state.variant==='3'?w.start3:w.start7, now=new Date();$('#month').textContent=hebrewDateText(start);renderMoladYear(w.molad.getYear(),w.molad.getMonth());renderDatePair($('#start'),start);renderDatePair($('#end'),w.end);$('#hebrew-date-note').textContent=state.coords?(state.lang==='he'?'התאריכים העבריים מתחלפים בשקיעה המחושבת במיקום שנבחר; בדקו זמן מקומי.':'Hebrew dates advance at calculated sunset for the selected location; check local times.'):(state.lang==='he'?'ללא מיקום: התאריך העברי מוצג לפי יום התאריך האזרחי. אחרי השקיעה הוא עשוי להיות היום הבא; בחרו מיקום להתאמה.':'Without a location, Hebrew dates follow the displayed civil day. After sunset the Hebrew day may be the next day; choose a location to adjust.');$('#status').textContent=state.lang==='he'?(now<start?'עוד לא התחיל':now>w.end?'הזמן הסתיים':'בתוך הזמן המחושב'):(now<start?'Coming up':now>w.end?'Window has passed':'Within the calculated window');$('#status').className='pill '+(now>=start&&now<=w.end?'active':'');$('#alt-times').textContent=`Other opinions: 3 days from molad ${fmt(w.start3)} · 7 days ${fmt(w.start7)} · 15-day limit ${fmt(w.end15)}. Times shown for the selected location when weather data is available; otherwise in your device timezone.`;renderCompletion();const s=sky();renderCountdown();renderMoonExtras();$('#sky').textContent=state.lang==='he'?(s?`הלבנה כרגע: ${Math.round(s.alt)}° מעל האופק, ${bearingName(s.az)} (${Math.round(s.az)}°). ${s.alt<5?'הלבנה נמוכה כרגע.':s.sunAlt>-6?'ייתכן שהשמים עדיין מוארים מדי.':'בדקו שהלבנה אכן נראית בשמים.'}`:'אפשרו מיקום כדי לראות את כיוון הלבנה ושטחים פתוחים קרובים.'):s?`Moon right now: ${Math.round(s.alt)}° above horizon, ${bearingName(s.az)} (${Math.round(s.az)}°). ${s.alt<5?'Too low to rely on a clear view now.':s.sunAlt>-6?'Sky may still be too light.':'Look up and confirm you can actually see it.'}`:'Enable location to see the moon’s direction and nearby open spaces.'}
function renderCountdown(){const w=windowNow(),now=new Date(),end=w.end,ms=end-now,start=state.variant==='3'?w.start3:w.start7,el=$('#countdown');if(!el)return;
 const nights=Math.max(0,Math.ceil(ms/86400000));el.textContent=state.lang==='he'?(now<start?`עוד ${nights} לילות עד הגבול המחושב; תחילת המנהג שבחרתם טרם הגיעה.`:ms<0?'הגבול המחושב עבר. בדקו את מנהגכם.':`עוד כ-${nights} לילות עד הגבול המחושב (${fmt(end)}).`):(now<start?`${nights} nights until the calculated latest time; your selected start has not arrived yet.`:ms<0?'The calculated latest time has passed. Check your practice.':`About ${nights} nights left until the calculated latest time (${fmt(end)}).`)}
function renderForecast(){const el=$('#forecast');if(!el)return;if(!state.coords){el.textContent=state.lang==='he'?'בחרו מיקום כדי לראות תחזית עננות ללילה הקרוב.':'Choose your location to see tonight’s cloud forecast.';return}if(!state.forecast){el.textContent=state.lang==='he'?'ממתינים לתחזית עננות...':'Waiting for cloud forecast...';return}const f=state.forecast;if(f.noMoon){el.textContent=state.lang==='he'?'לא נמצאו שעות חשוכות עם לבנה מעל 5° ב־18 השעות הקרובות. בדקו שוב בהמשך.':'No dark hours with the moon above 5° in the next 18 hours. Check again later.';return}if(f.error){el.textContent=state.lang==='he'?'תחזית העננות אינה זמינה כרגע. בדקו שמים בפועל.':'Cloud forecast unavailable. Check the sky outside.';return}const verdict=state.lang==='he'?(f.cloud<35&&f.rain<30?'ייתכנו תנאים נוחים.':f.cloud>75||f.rain>60?'עננות/גשם עשויים להסתיר את הלבנה.':'הסיכוי לראותה אינו ודאי.'):(f.cloud<35&&f.rain<30?'Skies may be promising.':f.cloud>75||f.rain>60?'Cloud/rain may hide the moon.':'Visibility is uncertain.');el.textContent=state.lang==='he'?`תחזית לשעות החשיכה הקרובות (${f.hours} שעות): עננות ממוצעת ${f.cloud}%, סיכוי מרבי לגשם ${f.rain}%. ${verdict} תחזית בלבד, לא אישור שהלבנה תיראה; עצים ומבנים אינם נכללים.`:`Next dark hours (${f.hours} hours): average cloud cover ${f.cloud}%, peak rain chance ${f.rain}%. ${verdict} Forecast only: this cannot confirm the moon will be visible; buildings and trees are not included.`}
async function loadForecast(){if(!state.coords)return;const {lat,lon}=state.coords,token=`${lat.toFixed(5)},${lon.toFixed(5)}`;state.forecast=null;state.forecastCoords=token;renderForecast();try{const u=new URL('https://api.open-meteo.com/v1/forecast');for(const [k,v] of Object.entries({latitude:lat,longitude:lon,hourly:'cloud_cover,precipitation_probability',forecast_hours:24,timezone:'auto'}))u.searchParams.set(k,v);const response=await fetch(u);if(!response.ok)throw Error('Weather service');const data=await response.json();if(token!==state.forecastCoords)return;state.locationTimezone=data.timezone||null;renderTime();const h=data.hourly;if(!h?.time?.length)throw Error('Empty forecast');const entries=h.time.map((time,i)=>({time:new Date(time+localOffset(data.utc_offset_seconds)),cloud:h.cloud_cover[i],rain:h.precipitation_probability[i]}));const now=Date.now(),dark=entries.filter(e=>e.time.getTime()>=now&&e.time.getTime()<=now+18*3600000&&SunCalc.getPosition(e.time,lat,lon).altitude< -6&&SunCalc.getMoonPosition(e.time,lat,lon).altitude>5).slice(0,6);if(!dark.length){state.forecast={noMoon:true};state.lastForecastAt=Date.now();renderForecast();return}const cloud=Math.round(dark.reduce((a,b)=>a+(Number(b.cloud)||0),0)/dark.length),rain=Math.max(...dark.map(e=>Number(e.rain)||0));let verdict=state.lang==='he'?(cloud<35&&rain<30?'ייתכנו תנאים נוחים.':cloud>75||rain>60?'עננות/גשם עשויים להסתיר את הלבנה.':'הסיכוי לראותה אינו ודאי.'):(cloud<35&&rain<30?'Skies may be promising.':cloud>75||rain>60?'Cloud/rain may hide the moon.':'Visibility is uncertain.');state.forecast={hours:dark.length,cloud,rain,verdict};state.lastForecastAt=Date.now();renderForecast();checkGoodNight()}catch(e){if(token===state.forecastCoords){state.forecast={error:true};state.lastForecastAt=Date.now();renderForecast()}}}
function localOffset(seconds){const minutes=Math.round((Number(seconds)||0)/60),sign=minutes>=0?'+':'-',m=Math.abs(minutes);return `${sign}${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
// Azimuth is north-clockwise degrees in this SunCalc version. The graphic is north-up
// unless the user explicitly enables an available device-heading sensor.
function localDay(date,tz){return new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function tonightMoonrise(){if(!state.coords||!state.locationTimezone)return null;
 const {lat,lon}=state.coords,tz=state.locationTimezone,today=localDay(new Date(),tz),times=[];
 for(let d=-1;d<=1;d++){const day=new Date(Date.now()+d*86400000),rise=SunCalc.getMoonTimes(day,lat,lon).rise;if(rise&&localDay(rise,tz)===today&&!times.some(x=>x.getTime()===rise.getTime()))times.push(rise)}
 return times.sort((a,b)=>a-b)[0]||undefined;
}
function renderMoonExtras(){const compass=$('#moon-compass'),rise=$('#moonrise');if(!compass||!rise)return;
 const s=sky(),he=state.lang==='he';if(!s){compass.hidden=false;$('#compass-bearing').textContent=he?'מצפן ללבנה':'Moon compass';$('#compass-note').textContent=he?'בחרו מיקום כדי לחשב כיוון אמיתי ללבנה.':'Choose your location to calculate the moon direction.';$('#compass-arrow').hidden=true;$('#enable-heading').disabled=true;rise.textContent=he?'🌙 זריחת הלבנה היום: בחרו מיקום להצגת השעה.':'🌙 Moonrise today: choose your location to see the time.';return}
 compass.hidden=false;$('#compass-arrow').hidden=false;$('#enable-heading').disabled=false;const heading=Date.now()-state.compassLastAt<10000?state.compassHeading:null;
 $('#compass-arrow').style.transform=`rotate(${s.az-(heading??0)}deg)`;
 $('#compass-north').style.transform=`rotate(${- (heading??0)}deg)`;
 $('#compass-bearing').textContent=he?`כיוון ${Math.round(s.az)}° מצפון · גובה ${Math.round(s.alt)}°`:`${Math.round(s.az)}° from north · ${Math.round(s.alt)}° high`;
 $('#enable-heading').textContent=heading!==null?(he?'מצפן חי פעיל':'Live compass active'):(he?'הפעלת מצפן חי':'Enable live compass');if(state.compassFailure&&heading===null){$('#compass-note').textContent=he?'לא התקבל כיוון מהחיישן. החץ מוצג ביחס לצפון; השתמשו במצפן נפרד.':'No compass heading received. The arrow is north-up; use a separate compass.'}else $('#compass-note').textContent=heading===null?(he?'החץ ביחס לצפון, לא לכיוון שאתם מחזיקים את הטלפון. כוונו לפי מצפן.':'North-up reference, not your phone direction. Enable live compass and hold the phone flat, away from metal. If sensors are unavailable, use a separate compass.'):(he?'כיוון חי: החזיקו את הטלפון שטוח והסתובבו עד שהחץ פונה למעלה. מתכת עלולה לשבש חיישנים. בדקו שהלבנה נראית.':'Live direction: hold your phone flat and turn until the arrow points up. Sensors can drift near metal. Confirm the moon is visible; this is not a clear-view guarantee.');
 if(!state.locationTimezone){rise.textContent=he?'🌙 זריחת הלבנה היום: מחשבים את השעה המקומית...':'🌙 Moonrise today: calculating local time...';return}
 const r=tonightMoonrise();rise.textContent=r?(he?`🌙 זריחת הלבנה היום: ${fmt(r)} (מחושב לאופק שטוח).`:`🌙 Moonrise today: ${fmt(r)} (calculated for a level horizon).`):(he?'🌙 זריחת הלבנה היום: אין זריחה ביום המקומי הזה; ייתכן שזרחה קודם או שתזרח מחר.':'🌙 Moonrise today: no rise on this local calendar day; it may have risen earlier or rise tomorrow.');
}
async function enableHeading(){const note=$('#compass-note');if(state.compassListening){renderMoonExtras();return}
 try{if(!('DeviceOrientationEvent' in window))throw Error('unavailable');if(typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted')throw Error('denied');
 const listener=e=>{let h=Number.isFinite(e.webkitCompassHeading)?e.webkitCompassHeading:(e.absolute&&Number.isFinite(e.alpha)?(360-e.alpha)%360:null);if(h===null)return;state.compassHeading=h;state.compassLastAt=Date.now();state.compassFailure=false;renderMoonExtras()};
 window.addEventListener('deviceorientationabsolute',listener);window.addEventListener('deviceorientation',listener);state.compassListening=true;
 note.textContent=state.lang==='he'?'ממתינים לחיישן; אם לא יפעל, השתמשו בכיוון ביחס לצפון.':'Waiting for sensor; if unsupported, use the north-based bearing.';setTimeout(()=>{if(!state.compassLastAt){state.compassFailure=true;renderMoonExtras()}},6000);
 }catch{note.textContent=state.lang==='he'?'חיישן כיוון אינו זמין או שהרשות נדחתה. השתמשו בכיוון ביחס לצפון.':'Heading sensor unavailable or denied. Use the north-based bearing.'}
}
function renderAlert(){const b=$('#good-night-alert'),n=$('#alert-note');if(!b)return;const he=state.lang==='he';b.textContent=state.alertEnabled?(he?'כיבוי בדיקת הערב':'Turn off tonight check'):(he?'הפעלת בדיקת הערב':'Enable tonight check');b.setAttribute('aria-pressed',String(state.alertEnabled));
 n.textContent=state.alertEnabled?(he?'פעיל רק כשהאפליקציה פתוחה והמכשיר מחובר. בדיקה לכל היותר פעם בשעה; אין התראות רקע או Push.':'Only while this app is open and online. Checks at most hourly. No background alerts or push.'):(he?'בחרו מיקום ואז הפעילו. התרעה רק באפליקציה פתוחה, כשהתחזית והזמן המחושב מתאימים; לא הבטחה לראייה.':'Choose a location, then enable. Alerts only while the app is open, when the forecast and calculated window fit; not a visibility guarantee.');
}
async function toggleGoodNight(){if(state.alertEnabled){state.alertEnabled=false;localStorage.removeItem('levana-alert');renderAlert();return}
 if(!state.coords){$('#alert-note').textContent=state.lang==='he'?'בחרו מיקום תחילה.':'Choose a location first.';return}
 state.alertEnabled=true;localStorage.setItem('levana-alert','on');localStorage.setItem('levana-alert-coords',JSON.stringify(state.coords));renderAlert();
 if('Notification' in window&&'serviceWorker' in navigator&&Notification.permission==='default'){try{await Notification.requestPermission()}catch{}}
 checkGoodNight();
}
async function checkGoodNight(){if(isMonthComplete()||!state.alertEnabled||!state.coords||!state.forecast||state.forecast.error||state.forecast.noMoon||!state.locationTimezone||Date.now()-state.lastForecastAt>75*60000)return;
 const f=state.forecast,now=new Date(),w=windowNow(),start=state.variant==='3'?w.start3:w.start7;if(now<start||now>w.end||f.cloud>=35||f.rain>=30)return;const {lat,lon}=state.coords;if(SunCalc.getPosition(now,lat,lon).altitude>=-6||SunCalc.getMoonPosition(now,lat,lon).altitude<=5)return;
 const key=`${state.coords.lat.toFixed(3)},${state.coords.lon.toFixed(3)}:${localDay(now,state.locationTimezone)}`;
 if(localStorage.getItem('levana-alert-last')===key)return;
 const text=state.lang==='he'?'ייתכן שתנאי הלילה מתאימים לקידוש לבנה. בדקו שהלבנה נראית ואת מנהגכם.':'Tonight may work for Kiddush Levana. Check that the moon is visible and follow your practice.';
 $('#alert-note').textContent=text;localStorage.setItem('levana-alert-last',key);
 if('Notification' in window&&Notification.permission==='granted'&&'serviceWorker' in navigator){try{const reg=await navigator.serviceWorker.ready;await reg.showNotification(state.lang==='he'?'הלילה עשוי להתאים':'Tonight may work',{body:text,tag:'levana-good-night',icon:'/1-prayer-icon-192-v2.png'})}catch{}}
}
function toggleNight(){state.nightMode=!state.nightMode;localStorage.setItem('levana-night',state.nightMode?'on':'off');document.body.classList.toggle('night-red',state.nightMode);updateNightButton()}
