const TALLEST_TREE_M=120;
function environmentalSight(p,az,alt){if(alt<=0)return {status:'below'};if(!terrainReady)return {status:'uncertain',terrainMissing:true};const base=groundHeight(p.lat,p.lon);if(base===null)return {status:'uncertain',terrainMissing:true};let near=false;const low=Math.tan(Math.max(0,alt-.3)*Math.PI/180),high=Math.tan(Math.min(89.9,alt+.3)*Math.PI/180);for(const a of [az-2,az,az+2])for(let d=100;d<=TERRAIN_RANGE;d+=100){const lat=p.lat+d*Math.cos(a*Math.PI/180)/111320,lon=p.lon+d*Math.sin(a*Math.PI/180)/(111320*Math.cos(p.lat*Math.PI/180)),h=groundHeight(lat,lon);if(h===null)return {status:'uncertain',terrainMissing:true};const rise=h-base-d*d/(2*6371000);if(rise-10>1.6+d*high)return {status:'blocked',terrainBlocked:true,terrainDistance:d};if(rise+10>=1.6+d*low)near=true}if(near)return {status:'uncertain',terrainNear:true};const range=modelCoverage?.range||MODEL_RANGE;for(const w of state.woodlands||[]){if(insideBuilding(p,w))return {status:'uncertain',woods:true};for(const ring of polygons(w.geometry).flat()){const pts=ring.map(q=>localXY(q[1],q[0],p.lat,p.lon));for(const angle of [az-2,az,az+2]){const ray=[range*Math.sin(angle*Math.PI/180),range*Math.cos(angle*Math.PI/180)];for(let j=0;j<pts.length;j++)if(segmentCross([0,0],ray,pts[j],pts[(j+1)%pts.length])!==null){const t=segmentCross([0,0],ray,pts[j],pts[(j+1)%pts.length]);const crossing={lat:p.lat+t*range*Math.cos(angle*Math.PI/180)/111320,lon:p.lon+t*range*Math.sin(angle*Math.PI/180)/(111320*Math.cos(p.lat*Math.PI/180))};const gh=groundHeight(crossing.lat,crossing.lon);if(gh!==null&&t*range*low+1.6-(gh-base)>TALLEST_TREE_M)continue;const sample=canopySamples.find(q=>distance(crossing.lat,crossing.lon,q.lat,q.lon)<Math.max(8,q.patch_m/2));if(sample&&sample.lower_m+(groundHeight(crossing.lat,crossing.lon)??base)-base>1.6+t*range*high)return {status:'blocked',woods:true,canopyEstimated:true,canopyHeight:sample.median_m};return {status:'uncertain',woods:true,canopyEstimated:!!sample}}}}}return {status:'model-clear'}}

function sightLabel(s){if(s?.status==='no-data')return say('Unverified - no buildings mapped here. This does not prove a clear view.','לא מאומת - אין מבנים במפה כאן. אין בכך אישור לראייה פנויה.');if(!s)return say('Not checked','לא נבדק');if(s.status==='below')return say('Moon below horizon - no visible moon now','הלבנה מתחת לאופק - אינה נראית כעת');if(s.status==='inside')return say('Position is inside a mapped building. Choose a point outdoors.','המיקום בתוך מבנה במפה. בחרו נקודה בחוץ.');if(s.status==='blocked')return say(`Likely blocked: ~${s.first.height}m building, ${s.first.distance}m away`,`חסימה משוערת: מבנה בגובה ~${s.first.height} מ׳, במרחק ${s.first.distance} מ׳`);if(s.status==='uncertain')return say(`Unverified: ${s.unknown} building heights missing along the moon line`,`לא מאומת: חסרים גבהים של ${s.unknown} מבנים בכיוון הלבנה`);return say(`No mapped blocker in this ${(s.range/1000).toFixed(1)} km model - NOT a verified clear view`,`לא נמצא חוסם במודל בטווח ${(s.range/1000).toFixed(1)} ק״מ - הראות לא מאומתת`)}
function checkModelPlaces(){const date=viewDate();state.places=state.places.map(p=>{const m=SunCalc.getMoonPosition(date,p.lat,p.lon),s=modelSight(p,(m.azimuth+360)%360,m.altitude);if(s.status==='model-clear'){const env=environmentalSight(p,(m.azimuth+360)%360,m.altitude);Object.assign(s,env)}return {...p,sight:s,sightText:sightLabel(s)}}).sort((a,b)=>Number(!!b.here)-Number(!!a.here)||({ 'model-clear':0,uncertain:1,blocked:2,inside:3,below:4,'no-data':5}[a.sight.status])-({'model-clear':0,uncertain:1,blocked:2,inside:3,below:4,'no-data':5}[b.sight.status])||a.dist-b.dist);renderPlaces();const label=$('#checked-time');if(label)label.textContent=say('Checked for: ','נבדק לזמן: ')+new Intl.DateTimeFormat(state.lang==='he'?'he-IL':undefined,{dateStyle:'short',timeStyle:'short'}).format(date);showBuildingMap()}
function clearPlaceSuggestions(){const verified=[];for(const p of state.places.filter(p=>p.sight?.status==='model-clear').sort((a,b)=>a.dist-b.dist)){if(verified.every(q=>distance(p.lat,p.lon,q.lat,q.lon)>=40))verified.push(p);if(verified.length===1)break}return verified}
function streetLabel(p){return p.streetName||say('Street name not available in map data','שם הרחוב אינו זמין בנתוני המפה')}
const addrCache=new Map();
function addrKey(p){return state.lang+p.lat.toFixed(5)+','+p.lon.toFixed(5)}
async function loadAddress(p){const k=addrKey(p);if(addrCache.has(k))return;addrCache.set(k,'');try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=18&addressdetails=1&accept-language=${state.lang==='he'?'he':'en'}&lat=${p.lat}&lon=${p.lon}`,{signal:AbortSignal.timeout(8000)});if(r.ok){const j=await r.json(),a=j.address||{},l1=[a.road||a.pedestrian||a.footway||a.path||p.streetName,a.house_number].filter(Boolean).join(' '),l2=[a.postcode,a.city||a.town||a.village||a.suburb].filter(Boolean).join(' '),t=[l1,l2].filter(Boolean).join(', ');if(t)addrCache.set(k,t)}}catch{}renderPlaces()}
function renderPlaces(){const box=$('#places');if(!state.places.length){box.innerHTML='';return}const tally={};for(const x of state.places){const k=(x.sight?.status||'none')+(x.sight?.terrainNear?':terrainNear':'')+(x.sight?.terrainBlocked?':terrain':'')+(x.sight?.woods?':woods':'')+(x.sight?.unknown?':unk':'');tally[k]=(tally[k]||0)+1}box.dataset.tally=JSON.stringify(tally);const p=clearPlaceSuggestions()[0];if(!p){let reason=say('Try another time or location.','נסו שעה או מיקום אחרים.');if(!state.places.some(x=>x.sight)){box.innerHTML='';return}if(state.places.every(x=>x.sight?.status==='below'))reason=say('The moon is below the horizon. Try a later time.','הלבנה מתחת לאופק. נסו שעה מאוחרת יותר.');else if(state.places.some(x=>x.sight?.woods))reason=say('Woods nearby may block the moon.','יער בקרבת מקום עשוי להסתיר את הלבנה.');else if(state.places.some(x=>x.sight?.unknown))reason=say('Nearby buildings have no height data.','לבניינים בקרבת מקום אין נתוני גובה.');else if(state.places.some(x=>x.sight?.outside||x.sight?.terrainMissing))reason=say('Map data incomplete. Try again.','נתוני המפה חלקיים. נסו שוב.');box.innerHTML=`<div role="status" style="padding:16px;border:2px solid #b88d4d;border-radius:14px"><strong style="font-size:18px">${say('No verified spot nearby','לא נמצא מקום מאומת בסביבה')}</strong><p style="margin:6px 0 0">${esc(reason)}</p></div>`;return}
const m=SunCalc.getMoonPosition(viewDate(),p.lat,p.lon),az=(m.azimuth+360)%360,k=addrKey(p);if(!addrCache.has(k))loadAddress(p);const addr=addrCache.get(k)||p.streetName||p.lat.toFixed(5)+', '+p.lon.toFixed(5);
box.innerHTML=`<article style="padding:18px;border:2px solid #176b3b;border-radius:16px;background:#eef7ea;color:#1f3a24;margin:14px 0"><small style="font-weight:700;letter-spacing:.04em">${p.here?say('YOU CAN SEE IT RIGHT HERE','אפשר לראות אותה ממש כאן'):say('NEAREST SPOT','המקום הקרוב ביותר')}</small><div style="font-size:22px;font-weight:700;margin:8px 0">${esc(addr)}</div><div style="font-size:15px">${p.here?'':Math.round(p.dist)+' '+say('m','מ׳')+' · ~'+Math.max(1,Math.round(p.dist/80))+' '+say('min walk','דק׳ הליכה')+' · '}${say('Look','הביטו')} ${esc(bearingName(az))}, ${Math.round(m.altitude)}° ${say('up','מעלה')}</div><a target="_blank" rel="noopener" href="${mapLink(p)}" style="display:block;text-align:center;margin-top:14px;background:#176b3b;color:#fff!important;padding:15px;border-radius:12px;font-weight:700;font-size:18px;text-decoration:none">${say('Navigate →','נווטו ←')}</a><p style="margin:12px 0 0;font-size:12px;color:#456">${p.sight?.assumed?say('Some buildings have no height data; assumed up to '+p.sight.cap+' m. ','לחלק מהמבנים אין נתוני גובה; הוערך עד '+p.sight.cap+' מ׳. '):''}${say('From map data. Trees or unmapped buildings can still block.','לפי נתוני מפה. עצים או מבנים שלא במפה עשויים לחסום.')}</p></article>`}
async function findPlaces(){if(!state.coords)return;const run=++modelRun,{lat,lon}=state.coords;modelLoading=true;++canopyRun;canopySamples=[];terrainReady=false;modelCoverage=null;state.woodlands=[];if($('#checked-time'))$('#checked-time').textContent='';state.buildings=[];buildingIndex=null;state.places=[{lat,lon,name:say('Selected position','המיקום שנבחר'),here:true,dist:0}];$('#place-status').textContent=say('Loading 3D building model…','טוענים מודל מבנים בתלת־ממד…');renderPlaces();try{const data=await tileModel(lat,lon);if(run!==modelRun)return;modelCoverage=data.coverage;state.modelRoads=data.roads;state.woodlands=data.woodlands;state.buildings=data.buildings;let loadedTerrain=false;try{await loadTerrain(lat,lon,data.coverage.az);loadedTerrain=true}catch{}if(run!==modelRun)return;terrainReady=loadedTerrain;await loadCanopyEstimates(lat,lon,data.woodlands);if(run!==modelRun)return;renderCanopyEstimateNote();if(buildingMap)buildingMap.jumpTo({center:[lon,lat]});indexBuildings();const seen=new Set(),candidates=[];
 for(const road of [...data.namedRoads,...data.roads]){const lines=road.geometry.type==='LineString'?[road.geometry.coordinates]:road.geometry.coordinates;for(const line of lines)for(let i=1;i<line.length;i++){const a=line[i-1],b=line[i],steps=Math.max(1,Math.ceil(distance(a[1],a[0],b[1],b[0])/60));for(let j=0;j<=steps;j++){const q={lat:a[1]+(b[1]-a[1])*j/steps,lon:a[0]+(b[0]-a[0])*j/steps},d=distance(lat,lon,q.lat,q.lon),key=Math.round(q.lat*1500)+','+Math.round(q.lon*1500);if(d<35||d>700||seen.has(key)||state.buildings.some(b=>insideBuilding(q,b)))continue;seen.add(key);candidates.push({...q,dist:d,streetName:road.properties.name||null,name:road.properties.name||say('Nearby street / path','רחוב / שביל קרוב')})}}}
 state.places.push(...candidates.sort((a,b)=>a.dist-b.dist).slice(0,500));checkModelPlaces();renderPlaces();modelStatus();
 }catch(e){if(run!==modelRun)return;state.places.forEach(p=>{p.sight=null;p.sightText=say('Unverified - building data unavailable','לא מאומת - נתוני מבנים אינם זמינים')});$('#place-status').textContent=say(Math.abs(lat)>85?'Polar map coverage unavailable. View unverified.':'Building check incomplete: the required tiles could not all load within the mobile budget. Retry or choose a higher moon time.','בדיקת המבנים לא הושלמה: לא כל האריחים הנדרשים נטענו בתקציב הטלפון. נסו שוב או בחרו זמן שבו הלבנה גבוהה יותר.');renderPlaces()}finally{if(run===modelRun)modelLoading=false}}
function modelStatus(){const el=$('#place-status'),lim=$('#model-limits');if(el&&(state.buildings.length||state.places.some(p=>p.sight)))el.textContent='';if(lim&&state.buildings.length)lim.textContent=say(`${state.buildings.length} building shapes loaded. Height ranges, ${(modelCoverage?.range/1000||1.5).toFixed(1)} km moon-direction check (${modelCoverage?.tiles||0} tiles); 350m+ outside-building assumption. ${terrainReady?'Terrain sampled every 100m to 20km with a 10m allowance':'Terrain data unavailable; suggestions remain unverified'}; mapped woodland checked; canopy height patches estimated where available. Missing individual trees/buildings remain unknown. NOT 100% verified: GPS, missing buildings, roofs, hills and trees can change visibility. Street access is not verified.`,`${state.buildings.length} צורות מבנים נטענו. טווחי גובה משוערים, בדיקה בכיוון הלבנה עד ${(modelCoverage?.range/1000||1.5).toFixed(1)} ק״מ (${modelCoverage?.tiles||0} אריחים). הנחת גובה מחוץ לטווח: 350 מ׳ ומעלה. ${terrainReady?'פני השטח נדגמו כל 100 מ׳ עד 20 ק״מ עם מרווח 10 מ׳':'נתוני הקרקע אינם זמינים; ההצעות לא מאומתות'}; נבדק יער ממופה; גובה צמרות הוערך בנקודות זמינות. עצים ומבנים חסרים עדיין אינם ידועים. לא מאומת ב־100%: GPS, מבנים חסרים, גגות, גבעות ועצים עשויים לשנות את הראות. הגישה לרחובות לא אומתה.`)}
let buildingMap=null,mapLoad=null,mapGeneration=0,mapStarting=false,mapSpotMarkers=[],mapSuggestionKey='';
function destroyBuildingMap(){mapSuggestionKey='';mapSpotMarkers.forEach(m=>m.remove());mapSpotMarkers=[];mapGeneration++;mapStarting=false;if(buildingMap){buildingMap.remove();buildingMap=null}}
async function loadMapLibrary(){if(window.maplibregl)return window.maplibregl;if(mapLoad)return mapLoad;mapLoad=new Promise((resolve,reject)=>{if(!document.querySelector('#maplibre-style')){const link=document.createElement('link');link.id='maplibre-style';link.rel='stylesheet';link.href='https://unpkg.com/maplibre-gl@5.6.2/dist/maplibre-gl.css';document.head.append(link)}const script=document.createElement('script');script.src='https://unpkg.com/maplibre-gl@5.6.2/dist/maplibre-gl.js';const timer=setTimeout(()=>reject(Error('Map library timed out')),15000);script.onload=()=>{clearTimeout(timer);resolve(window.maplibregl)};script.onerror=()=>{clearTimeout(timer);reject(Error('Map library unavailable'))};document.head.append(script)}).catch(e=>{mapLoad=null;throw e});return mapLoad}
function mapFeatureCollection(features=[]){return {type:'FeatureCollection',features}}
function refreshBuildingMap(){if(!buildingMap||!state.coords)return;if(!buildingMap.isStyleLoaded()){buildingMap.once('idle',()=>refreshBuildingMap());return;}const {lat,lon}=state.coords,m=SunCalc.getMoonPosition(viewDate(),lat,lon),az=(m.azimuth+360)%360,near=state.buildings.filter(b=>{const p=polygons(b.geometry)[0]?.[0]?.[0];return p&&distance(lat,lon,p[1],p[0])<1800}).map(b=>({...b,properties:{...b.properties,uncertain:!Number.isFinite(heightRange(b)[1])}}));buildingMap.getSource('canopy').setData(mapFeatureCollection(canopySamples.map(p=>{const dy=Math.max(8,p.patch_m/2)/111320,dx=dy/Math.cos(p.lat*Math.PI/180);return {type:'Feature',properties:{height:p.median_m},geometry:{type:'Polygon',coordinates:[[[p.lon-dx,p.lat-dy],[p.lon+dx,p.lat-dy],[p.lon+dx,p.lat+dy],[p.lon-dx,p.lat+dy],[p.lon-dx,p.lat-dy]]]}}})));renderCanopyEstimateNote();buildingMap.getSource('woods').setData(mapFeatureCollection(state.woodlands||[]));buildingMap.getSource('buildings').setData(mapFeatureCollection(near));buildingMap.getSource('streets').setData(mapFeatureCollection(state.modelRoads||[]));const radians=az*Math.PI/180,endpoint=[lon+900*Math.sin(radians)/(111320*Math.cos(lat*Math.PI/180)),lat+900*Math.cos(radians)/111320];buildingMap.getSource('moon').setData(mapFeatureCollection([{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:[[lon,lat],endpoint]}}]));buildingMap.setPaintProperty('moon-ray','line-color',m.altitude>0?'#f4c542':'#888888');buildingMap.getSource('spots').setData(mapFeatureCollection([{type:'Feature',geometry:{type:'Point',coordinates:[lon,lat]},properties:{here:true}},...clearPlaceSuggestions().map(p=>({type:'Feature',geometry:{type:'Point',coordinates:[p.lon,p.lat]},properties:{here:false}}))]));mapSpotMarkers.forEach(m=>m.remove());mapSpotMarkers=[];for(const p of clearPlaceSuggestions()){const label=document.createElement('button');label.type='button';label.textContent=streetLabel(p);label.title=say('No mapped building blocker; estimated, not guaranteed visibility','אין חוסם לפי המפה; הערכה, ללא הבטחה לראייה');label.style.cssText='max-width:160px;padding:5px 8px;border:2px solid #fff;border-radius:8px;background:#176b3b;color:#fff;font-size:12px;line-height:1.3;box-shadow:0 2px 5px #0004';label.onclick=()=>buildingMap.flyTo({center:[p.lon,p.lat],zoom:18});mapSpotMarkers.push(new window.maplibregl.Marker({element:label,anchor:'bottom',offset:[0,-10]}).setLngLat([p.lon,p.lat]).addTo(buildingMap))}const suggestions=clearPlaceSuggestions(),key=suggestions.map(p=>p.lat.toFixed(5)+','+p.lon.toFixed(5)).join('|');if(key&&key!==mapSuggestionKey){mapSuggestionKey=key;const bounds=new window.maplibregl.LngLatBounds([lon,lat],[lon,lat]);suggestions.forEach(p=>bounds.extend([p.lon,p.lat]));buildingMap.fitBounds(bounds,{padding:{top:60,bottom:55,left:100,right:100},maxZoom:16.5,pitch:45,duration:0})}const note=$('#building-map-note');if(note)note.textContent=say(`Moon direction: ${bearingName(az)} (${Math.round(az)}°), ${m.altitude.toFixed(1)}° above horizon. Gold line = horizontal direction, not a 3D sightline. Green labels passed mapped buildings, sampled terrain and mapped-woodland screening. Green areas = mapped woods; raised green patches = sampled canopy-height estimates. Woods beyond the reach of any tree (taller than 120 m clearance) are ignored. Unsampled nearby trees stay uncertain. Not guaranteed visibility. Orange buildings have uncertain heights; drawn heights are estimates.`,`כיוון הלבנה: ${bearingName(az)} (${Math.round(az)}°), ${m.altitude.toFixed(1)}° מעל האופק. הקו הזהוב מציג כיוון אופקי, לא קו ראייה תלת־ממדי. תוויות ירוקות עברו בדיקת מבנים, קרקע מדוגמת ויער ממופה. שטחים ירוקים = יער ממופה; נקודות ירוקות מוגבהות = הערכות גובה צמרות שנדגמו. יערות רחוקים שאף עץ אינו מגיע אליהם (מעל 120 מ׳ מרווח) מתעלמים מהם. עצים קרובים שלא נדגמו נשארים לא ודאיים. אין הבטחה לראייה. מבנים כתומים הם בעלי גובה לא ודאי; הגבהים המוצגים משוערים.`);}
async function showBuildingMap(){const container=$('#building-map'),note=$('#building-map-note');if(!container||!state.coords)return;if(buildingMap){refreshBuildingMap();return}if(mapStarting)return;mapStarting=true;const generation=mapGeneration;note.textContent=say('Loading the 3D view…','טוענים תצוגת תלת־ממד…');try{const lib=await loadMapLibrary();if(generation!==mapGeneration||!container.isConnected)return;buildingMap=new lib.Map({container,style:{version:8,sources:{canopy:{type:'geojson',data:mapFeatureCollection()},terrain:{type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],tileSize:256,encoding:'terrarium',maxzoom:14},woods:{type:'geojson',data:mapFeatureCollection()},buildings:{type:'geojson',data:mapFeatureCollection()},streets:{type:'geojson',data:mapFeatureCollection()},moon:{type:'geojson',data:mapFeatureCollection()},spots:{type:'geojson',data:mapFeatureCollection()}},terrain:{source:'terrain',exaggeration:1},layers:[{id:'background',type:'background',paint:{'background-color':'#eae4d6'}},{id:'hills',type:'hillshade',source:'terrain',paint:{'hillshade-shadow-color':'#807860'}},{id:'woods',type:'fill',source:'woods',paint:{'fill-color':'#477b43','fill-opacity':.6}},{id:'canopy-patches',type:'fill-extrusion',source:'canopy',paint:{'fill-extrusion-color':'#396d31','fill-extrusion-height':['get','height'],'fill-extrusion-opacity':.65}},{id:'streets',type:'line',source:'streets',paint:{'line-color':'#fffdf7','line-width':6}},{id:'buildings',type:'fill-extrusion',source:'buildings',paint:{'fill-extrusion-color':['case',['boolean',['get','uncertain'],false],'#d2a16b','#a9b8bd'],'fill-extrusion-height':['max',3,['to-number',['get','render_height'],5]],'fill-extrusion-base':['to-number',['get','render_min_height'],0],'fill-extrusion-opacity':.9}},{id:'moon-ray',type:'line',source:'moon',paint:{'line-color':'#f4c542','line-width':5}},{id:'spots',type:'circle',source:'spots',paint:{'circle-radius':['case',['boolean',['get','here'],false],8,6],'circle-color':['case',['boolean',['get','here'],false],'#2563eb','#21864b'],'circle-stroke-color':'#ffffff','circle-stroke-width':2}}]},center:[state.coords.lon,state.coords.lat],zoom:17,pitch:55,bearing:0,maxPitch:70,attributionControl:false,antialias:true});buildingMap.addControl(new lib.NavigationControl({showCompass:true}),'top-right');buildingMap.on('load',()=>{refreshBuildingMap();buildingMap.resize()});buildingMap.on('error',()=>{if(note)note.textContent=say('3D view could not load. The building check and results below still work.','תצוגת התלת־ממד לא נטענה. בדיקת המבנים והתוצאות למטה עדיין פועלות.')});buildingMap.getCanvas().addEventListener('webglcontextlost',()=>{note.textContent=say('3D graphics unavailable. Use the results below.','תלת־ממד אינו זמין. השתמשו בתוצאות למטה.')});}catch(e){note.textContent=say('3D graphics unavailable on this browser. The building results below still work.','תצוגת תלת־ממד אינה זמינה בדפדפן זה. תוצאות המבנים למטה עדיין פועלות.')}finally{if(generation===mapGeneration)mapStarting=false}}

function setupBuildingModel(){destroyBuildingMap();const el=$('#model-controls');if(!el)return;el.innerHTML=`<p><label for="view-time">${say('Time (empty = now)','שעה (ריק = עכשיו)')}</label><input id="view-time" type="datetime-local" style="width:100%;box-sizing:border-box;margin-top:8px;padding:10px"></p><div id="building-map" role="region" aria-label="${say('3D map','מפת תלת־ממד')}" style="height:340px;width:100%;border-radius:12px;overflow:hidden;margin-top:12px;border:1px solid #c8b48e"></div><details><summary>${say('Details','פרטים')}</summary><p id="canopy-estimates" class="muted"></p><p id="building-map-note" class="muted"></p><p id="model-limits" class="muted"></p></details>`;$('#view-time').onchange=()=>{if(state.coords)findPlaces()};modelStatus();if(state.coords)showBuildingMap()}

let locationRequest=0;
function locate(){const request=++locationRequest,button=$('#locate');if(!navigator.geolocation){$('#place-status').textContent=say('Location is unavailable. Enter coordinates below.','המיקום אינו זמין. הזינו קואורדינטות למטה.');return}button.disabled=true;$('#place-status').textContent=say('Allow location in the browser prompt. Turn on phone Location/GPS.','אשרו גישה למיקום בחלון הדפדפן והפעילו מיקום/GPS בטלפון.');let finished=false;const done=()=>{if(finished||request!==locationRequest)return false;finished=true;clearTimeout(timer);button.disabled=false;return true};const timer=setTimeout(()=>{if(!done())return;$('#place-status').textContent=say('Location is still unavailable. Allow this site in Chrome > Site settings > Location, then try again. Or enter coordinates below.','המיקום עדיין אינו זמין. אשרו לאתר גישה למיקום בהגדרות האתר ב־Chrome ונסו שוב, או הזינו קואורדינטות למטה.')},20000);navigator.geolocation.getCurrentPosition(p=>{if(!done())return;state.coords={lat:p.coords.latitude,lon:p.coords.longitude};state.locationTimezone=null;state.forecast=null;state.forecastCoords=null;state.clearSkyCandidates=null;if(state.alertEnabled)localStorage.setItem('levana-alert-coords',JSON.stringify(state.coords));renderClearSky();$('#position').textContent=`${state.lang==='he'?'ליד':'Near'} ${state.coords.lat.toFixed(3)}, ${state.coords.lon.toFixed(3)} · accuracy ±${Math.round(p.coords.accuracy)} m`;renderTime();loadForecast();findPlaces()},e=>{if(!done())return;$('#place-status').textContent=e.code===1?say('Location permission is blocked. Allow this site in Chrome > Site settings > Location, then try again.','הגישה למיקום חסומה. אשרו גישה בהגדרות האתר ב־Chrome ונסו שוב.'):say('Location unavailable. Turn on Location/GPS and try again, or enter coordinates below.','המיקום אינו זמין. הפעילו מיקום/GPS ונסו שוב, או הזינו קואורדינטות למטה.')},{enableHighAccuracy:true,timeout:14000,maximumAge:60000})}

const whatsAppText='שלום עליכם';
const whatsAppQuery='?text=%D7%A9%D7%9C%D7%95%D7%9D+%D7%A2%D7%9C%D7%99%D7%9B%D7%9D';
function contactPhone(raw){const digits=String(raw||'').replace(/\D/g,'');return /^[1-9]\d{7,14}$/.test(digits)?digits:null}
function renderContacts(){const box=$('#contacts');box.innerHTML=state.selected.map((c,i)=>{const number=contactPhone(c.phone);return `<div class="contact"><div><b>${i+1}. ${esc(c.name||c.phone||'Person')}</b><small>${esc(c.phone||'No number')}</small></div><div class="contact-actions">${number?`<a href="tel:+${number}" aria-label="${state.lang==='he'?'התקשרו אל':'Call'} ${esc(c.name||c.phone)}">${state.lang==='he'?'התקשרו':'Call'}</a><a target="_blank" rel="noopener" href="https://wa.me/${number}${whatsAppQuery}" aria-label="${state.lang==='he'?'הודעת WhatsApp אל':'WhatsApp message to'} ${esc(c.name||c.phone)}">${state.lang==='he'?'הודעה ב-WhatsApp':'Message on WhatsApp'}</a>`:''}<button data-remove="${i}" aria-label="${state.lang==='he'?'הסרת':'Remove'} ${esc(c.name||c.phone||'person '+(i+1))}">${state.lang==='he'?'מחיקה':'Delete'}</button></div></div>`}).join('');$('#contact-count').textContent=`${state.selected.length}/3 ${state.lang==='he'?'אנשים נבחרו':'people selected'}`;box.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.selected.splice(+b.dataset.remove,1);renderContacts()})}
async function pickContacts(){if(!navigator.contacts?.select){$('#contact-note').textContent='Contact Picker is not supported here. Add a number manually or use Share.';return}try{const picked=await navigator.contacts.select(['name','tel'],{multiple:true});for(const p of picked){if(state.selected.length>=3)break;let phone=p.tel?.[0]||'';if(!state.selected.some(c=>c.phone===phone&&phone))state.selected.push({name:p.name?.[0]||'',phone})}renderContacts()}catch(e){$('#contact-note').textContent='Could not open contacts. You can add numbers manually.'}}
async function share(){if(navigator.share){try{await navigator.share({text:'שלום עליכם'});return}catch{}}try{await navigator.clipboard.writeText('שלום עליכם');$('#contact-note').textContent='Copied שלום עליכם. Paste it to the people you choose.'}catch{$('#contact-note').textContent='Share or copy שלום עליכם to the people you choose.'}}
function init(){document.querySelector('#app').innerHTML=`<header><div class="brand"><img class="brand-art" src="/5-prayer-header-edge-free.png" alt="" width="112" height="82"><div><h1>קידוש לבנה</h1></div></div><div class="header-controls"><button id="lang-toggle" aria-label="Switch language">עברית</button><button id="torch" aria-label="Toggle flashlight">Flashlight ◉</button><button id="night-toggle" type="button" aria-pressed="false">Red night mode</button><span id="flash-notice" class="flash-notice" role="status"></span></div></header><main><section class="hero"><h2>Kiddush Levana</h2></section><section class="grid"><article class="card"><div class="card-head"><span>01 / THE WINDOW</span><span id="status" class="pill"></span></div><h3 id="month"></h3><details class="molad-details"><summary style="padding:16px;border:1px solid #b88d4d;border-radius:12px;background:#efe0bf;font-weight:700;min-height:48px;box-sizing:border-box;margin:14px 0">${state.lang==='he'?'מולד וזמני קידוש לבנה ▾':'Molad & Kiddush Levana times ▾'}</summary><p id="molad-year-label" style="font-weight:700"></p><p class="muted" style="font-size:12px">${state.lang==='he'?'מולד חשבוני. הכרזה: זמן ירושלים ממוצע; שעות אחרות: זמן מקומי. מברכים רק בלילה כשהלבנה נראית.':'Calculated molad. Announcement: Jerusalem mean time; other times: local. Bless only at night with a visible moon.'} <a href="https://www.hebcal.com/" target="_blank" rel="noopener">${state.lang==='he'?'מקור':'Source'}</a></p><div id="molad-year-list"></div></details><p id="countdown" class="countdown"></p><div class="practice-control"><label for="variant">Earliest practice</label><select id="variant"><option value="3">${state.lang==='he'?'ג׳ ימים (ב״ח - גר״א)':'3 days (Bach - Gra)'}</option><option value="7">${state.lang==='he'?'ז׳ ימים (מחבר)':'7 days (Mechaber)'}</option></select></div><p class="muted practice-sources">${state.lang==='he'?'ג׳ ימים מלאים מהמולד:':'3 full days from the molad:'} <a href="https://wiki.jewishbooks.org.il/mediawiki/wiki/%D7%91%22%D7%97/%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D/%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'ב״ח או״ח תכו':'Bach, OC 426'}</a>; <a href="https://he.wikisource.org/wiki/%D7%91%D7%99%D7%90%D7%95%D7%A8_%D7%94%D7%9C%D7%9B%D7%94_%D7%A2%D7%9C_%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D_%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'ביאור הלכה תכו:ב, ד״ה במוצאי שבת (ב״ח - גר״א)':'Biur Halacha 426:2, “On Saturday night” (Bach - Gra)'}</a>; <a href="https://he.wikisource.org/wiki/%D7%9E%D7%92%D7%9F_%D7%90%D7%91%D7%A8%D7%94%D7%9D_%D7%A2%D7%9C_%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D_%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'מגן אברהם תכו:יג':'Magen Avraham 426:13'}</a>.<br>${state.lang==='he'?'ז׳ ימים:':'7 days:'} <a href="https://he.wikisource.org/wiki/%D7%A9%D7%95%D7%9C%D7%97%D7%9F_%D7%A2%D7%A8%D7%95%D7%9A_%D7%90%D7%95%D7%A8%D7%97_%D7%97%D7%99%D7%99%D7%9D_%D7%AA%D7%9B%D7%95" target="_blank" rel="noopener">${state.lang==='he'?'שולחן ערוך תכו:ד (מחבר)':'Shulchan Arukh 426:4 (Mechaber)'}</a>.<br>${state.lang==='he'?'בחרו לפי מנהג הקהילה; הזמן המחושב אינו פסק הלכה.':"Follow your community's practice; the calculated time is not a ruling."}</p><div class="times"><div><span>EARLIEST CALCULATED TIME</span><b id="start"></b></div><div><span>LAST TIME · HALF A LUNAR MONTH</span><b id="end"></b></div></div><p id="hebrew-date-note" class="muted"></p><div class="actions"><button id="add-calendar">Add to calendar / Reminder</button><button id="download-ics">Download .ics</button></div><p class="muted" id="reminder-note">Calendar event starts at your selected earliest calculated time. Review the time and alert in your calendar.</p><details><summary>Other opinions & important notes</summary><p id="alt-times"></p><p>These are molad-based calculations, not a ruling. Say the blessing only when the moon is actually visible, at night. Customs differ on the first and last permissible time, Shabbat/Yom Tov, and the month of Tishrei. Check your own community’s practice and local nightfall.</p><p>Source: <a href="https://www.hebcal.com/" target="_blank" rel="noopener">Hebcal molad methods</a>.</p></details></article><article class="card"><div class="card-head"><span>02 / FIND THE MOON</span><span>☾</span></div><h3>Moon and places</h3><p id="sky" class="sky"></p><div class="moon-extras"><div id="moon-compass" class="compass-block" hidden><div class="dial" role="img" aria-label="Moon bearing compass"><div id="compass-north" class="dial-north">N</div><div id="compass-arrow" class="dial-arrow">↑</div><div class="dial-moon">☾</div></div><b id="compass-bearing"></b><p id="compass-note" class="muted"></p><button id="enable-heading" type="button">Use phone heading</button></div><p id="moonrise" class="moonrise-highlight" role="status"></p></div><button id="locate" class="primary" style="width:100%;font-size:18px;padding:16px">${say('Find my spot ☾','מצאו לי מקום ☾')}</button><p id="position" class="muted"></p><details><summary>Enter coordinates instead</summary><div class="coord"><input id="lat" type="number" step="any" min="-90" max="90" placeholder="Latitude" aria-label="Latitude"><input id="lon" type="number" step="any" min="-180" max="180" placeholder="Longitude" aria-label="Longitude"><button id="use-coords">Search</button></div></details><p id="place-status" class="muted"></p><div id="places"></div><p id="checked-time" class="muted"></p><div id="model-controls"></div><details><summary>${say('Weather & clear sky','מזג אוויר ושמיים בהירים')}</summary><div class="forecast"><b>Tonight’s clouds</b><p id="forecast" class="muted"></p><small>Forecast: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>. Your location is only used for this forecast and map check.</small><div class="alert-control"><button id="good-night-alert" type="button" aria-pressed="false">Enable tonight check</button><p id="alert-note" class="muted"></p></div><div class="clear-sky"><button id="find-clear-sky" type="button">Find a clearer sky nearby ↗</button><p id="clear-sky-result" class="muted"></p><small>Searches forecast points out to 300 km worldwide. It does not verify accessible land, travel time, terrain, buildings or a clear view at a specific street.</small></div></div></details><details><summary>${say('Sources','מקורות')}</summary><p class="source">Canopy © Meta/WRI 2024, source imagery © 2016 Maxar, <a href="https://registry.opendata.aws/dataforgood-fb-forests/" target="_blank" rel="noopener">CC-BY-4.0 dataset</a>. Terrain: <a href="https://github.com/tilezen/joerd/blob/master/docs/attribution.md" target="_blank" rel="noopener">Mapzen and elevation source credits</a> (Austria © offene Daten Österreichs - DGM Österreich; EU-DEM © Copernicus/EU; SRTM/GMTED/3DEP courtesy USGS). Map data © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>. Walking directions open Google Maps.</p></details></article></section><section class="card join"><div class="card-head"><span>JOIN TONIGHT</span><span>☾</span></div><h3>Share tonight’s moon</h3><p>Invite someone to say קידוש לבנה with you tonight. WhatsApp opens a draft; you choose the person and send it yourself.</p><a id="share-invite" class="action-link" href="https://wa.me/?text=I%27m+saying+%D7%A7%D7%99%D7%93%D7%95%D7%A9+%D7%9C%D7%91%D7%A0%D7%94+tonight.+Join+me%3F+https%3A%2F%2Flevana-kiddush-levana.vercel.app%2F" target="_blank" rel="noopener">Invite via WhatsApp ↗</a><div id="minyan"></div></section><section id="nusach" class="card reading"><div class="card-head"><span>03 / THE WORDS</span><span>קידוש לבנה</span></div><h3>קידוש לבנה</h3><div class="prayer-controls"><label for="nusach-choice">Nusach / נוסח</label><select id="nusach-choice"><option value="ashkenaz">נוסח אשכנז</option><option value="edot">נוסח עדות המזרח</option></select></div><p id="prayer-source" class="muted"></p><div id="prayer" dir="rtl" lang="he"></div></section><section class="card greeting"><div class="card-head"><span>04 / SHARE THE GREETING</span><span>שלום עליכם</span></div><h3>Say hello to three people</h3><p>Traditionally said in person to three people, who answer "עליכם שלום". If they're not with you, you can call or message them instead.</p><div class="greeting-text" dir="rtl">שָׁלוֹם עֲלֵיכֶם</div><p id="contact-count" class="muted"></p><div id="contacts"></div><div class="actions"><button id="pick">Choose from contacts</button><a id="whatsapp-any" class="action-link" target="_blank" rel="noopener" href="https://wa.me/?text=%D7%A9%D7%9C%D7%95%D7%9D+%D7%A2%D7%9C%D7%99%D7%9B%D7%9D">Message via WhatsApp</a></div><div class="coord"><input id="person" placeholder="Name (optional)" aria-label="Contact name"><input id="phone" type="tel" placeholder="Phone with country code" aria-label="Phone number"><button id="add">Add</button></div><p id="contact-note" class="muted">Only you choose and contact people. The app never sends anything for you. WhatsApp opens a chat with the greeting ready for you to send.</p></section><footer>Times are calculated. Check local practice and visibility.</footer></main>`;
$('#add-calendar').onclick=()=>{const w=windowNow(),start=state.variant==='3'?w.start3:w.start7;const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const end=new Date(start.getTime()+30*60000);const q=new URLSearchParams({action:'TEMPLATE',text:'קידוש לבנה - תחילת הזמן',dates:stamp(start)+'/'+stamp(end),details:'Molad-based estimate; check local nightfall, visibility and your minhag.'});window.open('https://calendar.google.com/calendar/render?'+q.toString(),'_blank','noopener')};$('#download-ics').onclick=downloadReminder;$('#lang-toggle').onclick=()=>{const time=$('#view-time')?.value||'';state.lang=state.lang==='en'?'he':'en';localStorage.setItem('levana-lang',state.lang);init();$('#view-time').value=time;if(state.coords)findPlaces()};$('#torch').onclick=toggleFlashlight;$('#night-toggle').onclick=toggleNight;$('#nusach-choice').value=state.nusach;$('#nusach-choice').onchange=e=>{state.nusach=e.target.value;localStorage.setItem('levana-nusach',state.nusach);renderPrayer();applyNusachAccess()};$('#variant').value=state.variant;$('#variant').onchange=e=>{state.variant=e.target.value;localStorage.setItem('levana-variant',state.variant);renderTime()};$('#locate').onclick=locate;$('#find-clear-sky').onclick=findClearSky;$('#enable-heading').onclick=enableHeading;$('#good-night-alert').onclick=toggleGoodNight;$('#use-coords').onclick=()=>{const lat=Number($('#lat').value),lon=Number($('#lon').value);if(!$('#lat').value||!$('#lon').value||Math.abs(lat)>90||Math.abs(lon)>180){$('#place-status').textContent='Enter valid latitude and longitude.';return}state.coords={lat,lon};state.locationTimezone=null;state.forecast=null;state.forecastCoords=null;state.clearSkyCandidates=null;if(state.alertEnabled)localStorage.setItem('levana-alert-coords',JSON.stringify(state.coords));renderClearSky();$('#position').textContent=`${state.lang==='he'?'ליד':'Near'} ${lat.toFixed(3)}, ${lon.toFixed(3)}`;renderTime();loadForecast();findPlaces()};$('#pick').onclick=pickContacts;$('#add').onclick=()=>{if(state.selected.length>=3){$('#contact-note').textContent='Three people are already selected.';return}let phone=$('#phone').value.trim();if(!/^\+?[\d\s().-]{6,25}$/.test(phone)||!contactPhone(phone)){ $('#contact-note').textContent='Enter a phone number with country code.';return}state.selected.push({name:$('#person').value.trim(),phone});$('#person').value='';$('#phone').value='';renderContacts()};renderPrayer();renderTime();renderForecast();renderAlert();renderClearSky();renderPlaces();renderContacts();if(state.coords){$('#lat').value=state.coords.lat;$('#lon').value=state.coords.lon;$('#position').textContent=`${state.lang==='he'?'ליד':'Near'} ${state.coords.lat.toFixed(3)}, ${state.coords.lon.toFixed(3)}`}applyLanguage();updateNightButton();document.body.classList.toggle('night-red',state.nightMode);if(state.coords&&!state.forecast)loadForecast();setupViews();setupBuildingModel();if(state.buildings.length)checkModelPlaces();modelStatus()}
function downloadReminder(){const w=windowNow(),start=state.variant==='3'?w.start3:w.start7,end=new Date(start.getTime()+30*60000);const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Levana//Kiddush Levana//EN','BEGIN:VEVENT','UID:levana-'+stamp(start)+'@levana.local','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:קידוש לבנה - תחילת הזמן','DESCRIPTION:Calculated from molad. Check local nightfall, visibility and your minhag.','BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:קידוש לבנה','TRIGGER:PT0M','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n')+'\r\n';const url=URL.createObjectURL(new Blob([data],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='kiddush-levana-reminder.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function renderPrayer(){
 const isEdot=state.nusach==='edot',parts=isEdot?edot:nusach;
 $('#prayer').innerHTML=parts.map(p=>`<p class="${p.type}">${esc(p.text)}</p>`).join('');
 if(!isEdot){const after=$('#prayer p:last-child');after.insertAdjacentHTML('afterend',`<div class="song-option" dir="${state.lang==='he'?'rtl':'ltr'}"><h3>${state.lang==='he'?'לריקוד לפי המנהג':'For dancing by your custom'}</h3><p>${state.lang==='he'?'טובים מאורות (באבוב)':"Tovim Me'orot (Bobov)"}</p><audio controls preload="none" aria-label="טובים מאורות (באבוב)" src="/2-tovim-meoros.mp3">${state.lang==='he'?'הדפדפן אינו תומך בהשמעת הקובץ':'Your browser does not support audio playback'}</audio><p>${state.lang==='he'?"טובים מאורות (מודז'יץ)":"Tovim Me'orot (Modzitz)"}</p><audio controls preload="none" aria-label="טובים מאורות (מודז'יץ)" src="/1-tovim-meoros-modzitz.mp3">${state.lang==='he'?'הדפדפן אינו תומך בהשמעת הקובץ':'Your browser does not support audio playback'}</audio><p>${state.lang==='he'?'טובים מאורות (בעלזא)':"Tovim Me'orot (Belz)"}</p><audio controls preload="none" aria-label="טובים מאורות (בעלזא)" src="/3-tovim-meoros-belz-compatible.mp3">${state.lang==='he'?'הדפדפן אינו תומך בהשמעת הקובץ':'Your browser does not support audio playback'}</audio></div>`)}


 $('#prayer-source').innerHTML=isEdot?`<a href="https://www.sefaria.org/Siddur_Edot_HaMizrach%2C_Blessing_of_the_Moon" target="_blank" rel="noopener">${state.lang==='he'?'מקור הנוסח: סידור עדות המזרח בספריא':'Source: Sefaria, Siddur Edot HaMizrach'}</a>. ${state.lang==='he'?'מנהגים מקומיים עשויים להשתנות. בדקו בסידור שלכם. קדיש נאמר במניין בלבד.':'Local customs vary. Check your siddur. Kaddish requires a minyan.'}`:`<a href="https://he.wikisource.org/wiki/%D7%A7%D7%99%D7%93%D7%95%D7%A9_%D7%9C%D7%91%D7%A0%D7%94" target="_blank" rel="noopener">${state.lang==='he'?'מקור הנוסח: ויקיטקסט':'Source: Wikisource Ashkenaz siddur'}</a>. ${state.lang==='he'?'נכללים גם קטעי הסיום; תוספות ומנהגים שונים לפי קהילה. קדיש נאמר במניין בלבד.':'Concluding passages included; additions vary by community. Kaddish requires a minyan.'}`;
}
