async function pollJoin(){const a=minyanAuto();if(!a.on)return;try{const r=await fetch('/api/join?id='+a.id,{cache:'no-store'});if(!r.ok)throw 0;const j=await r.json();state.joinCount=j.count||0;state.joinErr=false;const key='levana-seen-'+a.id,first=localStorage.getItem(key)===null;let seen=[];try{seen=JSON.parse(localStorage.getItem(key)||'[]')}catch{}const fresh=(j.members||[]).filter(m=>!seen.includes(m.d));localStorage.setItem(key,JSON.stringify((j.members||[]).map(m=>m.d)));state.joinNames=(j.members||[]).map(m=>m.name).filter(Boolean);if(fresh.length&&!first)joinToast(fresh)}catch{state.joinErr=true}renderMinyan()}
