function renderMinyan(){const el=document.querySelector('#minyan');if(!el)return;const a=minyanAuto(),manual=minyanState().n,taps=a.on?(state.joinCount||0):0,n=a.on?Math.min(30,1+taps+manual):manual,done=n>=10,btn='width:40px;height:40px;min-height:0;font-size:22px;line-height:1;border-radius:50%;padding:0;flex:none',seg=on=>`border-radius:999px;padding:4px 10px;font-size:12px;min-height:0;white-space:nowrap;${on?'background:#176b3b;color:#fff':'background:#fff;color:#5a4a2a;border:1px solid #b88d4d'}`;const note=state.joinErr&&!taps?'':say(`${(state.joinNames||[]).length?state.joinNames.join(', ')+'. ':''}${taps?'You + '+taps+' joined by link'+(manual?' + '+manual+' added':'')+'. ':''}Friends who tap "I\'m in" on your invite are counted. Taps, not verified people.`,`${(state.joinNames||[]).length?state.joinNames.join(', ')+'. ':''}${taps?'אתם + '+taps+' הצטרפו בקישור'+(manual?' + '+manual+' הוספו':'')+'. ':''}מי שלוחץ "אני מצטרף" בהזמנה נספר. לחיצות, לא אנשים מאומתים.`);const pl=document.querySelector('#share-invite');if(pl)pl.textContent=say('Invite to my minyan ↗','הזמנה למניין שלי ↗');el.innerHTML=`<div style="margin-top:12px;padding:10px 12px;border:2px solid ${done?'#176b3b':'#b88d4d'};border-radius:16px;text-align:center;${done?'background:#eef7ea;color:#1f3a24':''}"><b style="font-size:14px">${say('Minyan','מניין')}</b><div style="display:flex;align-items:center;justify-content:center;gap:14px;margin:6px 0;flex-wrap:nowrap"><button type="button" id="minyan-minus" aria-label="${say('Remove one','הסר אחד')}" style="${btn}">−</button><div style="font-size:24px;font-weight:700;white-space:nowrap;min-width:84px">${n} / 10</div><button type="button" id="minyan-plus" aria-label="${say('Add one','הוסף אחד')}" style="${btn}">+</button></div><div style="height:6px;border-radius:3px;background:#e3d6b8;overflow:hidden"><div style="height:100%;width:${Math.min(100,n*10)}%;background:#176b3b"></div></div><p style="margin:6px 0 0;font-size:12px;line-height:1.35">${done?say('Minyan ✓','יש מניין ✓')+(note?'<br>':''):''}${note}</p></div>`;el.querySelector('#minyan-plus').onclick=()=>minyanSet(minyanState().n+1);el.querySelector('#minyan-minus').onclick=()=>minyanSet(minyanState().n-1)}
function joinLanding(){const id=new URLSearchParams(location.search).get('join');if(!id||!/^[a-z0-9]{8,40}$/.test(id))return;let d=localStorage.getItem('levana-device');if(!d){d=rid();localStorage.setItem('levana-device',d)}const done=localStorage.getItem('levana-joined-'+id)==='1',o=document.createElement('div');o.style.cssText='position:fixed;inset:0;z-index:9999;background:#fffaf0;display:flex;align-items:center;justify-content:center;padding:24px;text-align:center';const he=state.lang==='he';o.innerHTML=`<div style="max-width:340px"><div style="font-size:48px">☾</div><h2 style="margin:8px 0">${say('Join us for Kiddush Levana','הצטרפו אלינו לקידוש לבנה')}</h2><p id="jl-msg" style="font-size:16px"></p><input id="jl-name" maxlength="20" placeholder="${say('Your name (optional)','השם שלך (לא חובה)')}" style="width:100%;box-sizing:border-box;padding:12px;font-size:16px;margin:0 0 12px;border:1px solid #b88d4d;border-radius:12px;text-align:center"><button type="button" id="jl-in" style="width:100%;padding:16px;font-size:20px;border-radius:14px;background:#176b3b;color:#fff"></button><p><a href="#" id="jl-skip" style="font-size:14px">${say('Open the app','פתחו את האפליקציה')}</a></p></div>`;document.body.append(o);const b=o.querySelector('#jl-in'),m=o.querySelector('#jl-msg');const P=new URLSearchParams(location.search),lat=Number(P.get('lat')),lon=Number(P.get('lon')),addr=(P.get('a')||'').slice(0,90);const showLoc=()=>{if(!P.get('lat')||!isFinite(lat)||!isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||o.querySelector('#jl-loc'))return;const w=document.createElement('div');w.id='jl-loc';w.style.cssText='margin:14px 0;padding:12px;border:2px solid #b88d4d;border-radius:14px';const t=document.createElement('div');t.style.fontWeight='700';t.textContent=say('Meet here','נפגשים כאן');const ad=document.createElement('div');ad.textContent=addr;ad.style.cssText='margin:4px 0;font-size:14px';const l=document.createElement('a');l.className='action-link';l.target='_blank';l.rel='noopener';l.href='https://www.google.com/maps/dir/?api=1&destination='+lat.toFixed(5)+','+lon.toFixed(5)+'&travelmode=walking';l.textContent=say('Navigate ↗','ניווט ↗');w.append(t);if(addr)w.append(ad);w.append(l);b.after(w)};const setDone=()=>{showLoc();b.textContent=say('You are counted ✓','נספרתם ✓');b.disabled=true;o.querySelector('#jl-name').hidden=true;m.textContent=say('The host can see you are joining.','המארח רואה שאתם מצטרפים.')};if(done)setDone();else{b.textContent=say("I'm in",'אני מצטרף/ת');m.textContent=say('Tap to let the host know you are joining.','לחצו כדי להודיע למארח שאתם מצטרפים.');b.onclick=async()=>{b.disabled=true;try{const r=await fetch('/api/join?id='+id+'&d='+d+'&n='+encodeURIComponent((o.querySelector('#jl-name').value||'').trim()),{method:'POST'});if(!r.ok)throw 0;localStorage.setItem('levana-joined-'+id,'1');setDone()}catch{b.disabled=false;m.textContent=say('Could not send. Try again.','השליחה נכשלה. נסו שוב.')}}}o.querySelector('#jl-skip').onclick=e=>{e.preventDefault();o.remove()}}
joinLanding();
new MutationObserver(()=>{const el=document.querySelector('#minyan');if(el&&!el.dataset.r){el.dataset.r='1';renderMinyan();pollJoin()}}).observe(document.body,{childList:true,subtree:true});
document.addEventListener('click',e=>{if(e.target.closest&&e.target.closest('#lang-toggle'))setTimeout(renderMinyan,80)});
renderMinyan();pollJoin();
